<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/PrintifyAcceptanceFenceFixture.php';
use DigiForge\POD\{PrintifyAcceptanceEmergencyEvents as Events,PrintifyAcceptanceSafetyGeneration as Generation};
final class PrintifyAcceptanceEmergencyEventsTest extends WP_UnitTestCase {
 private array $settings=[];
 public function set_up():void {parent::set_up();global $wpdb;$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');$this->settings=$wpdb->get_results('SELECT * FROM '.\DigiForge\Database\Tables::settings(),ARRAY_A);\DigiForge\Core\Settings::protectProduction();$wpdb->delete($wpdb->options,['option_name'=>'df_acceptance_safety_generation_v1_quarantined']);}
 public function tear_down():void {remove_action('digiforge_emergency_stop_all_requested',[Events::class,'observe']);global $wpdb;$wpdb->query('ROLLBACK');$wpdb->query('DELETE FROM '.\DigiForge\Database\Tables::settings());foreach($this->settings as $row)$wpdb->insert(\DigiForge\Database\Tables::settings(),$row);parent::tear_down();}
 private function listen():string {self::assertTrue(class_exists(Events::class),'Configured pre-write emergency observer required');(new Events())->register();$g=Generation::terminate();self::assertNotWPError($g);return $g;}
 public function testRepeatedNativeStopAllCallsInvalidateEvenWhenAlreadyTrue():void {$a=$this->listen();self::assertTrue(\DigiForge\Core\Settings::get('stop_all',true));self::assertTrue(\DigiForge\Core\Settings::set('stop_all',true));self::assertWPError(Generation::check($a));$b=Generation::current();self::assertNotWPError($b);self::assertTrue(\DigiForge\Core\Settings::set('stop_all',true));self::assertWPError(Generation::check($b));}
 public function testFailedNativeStopWriteStillFencesOldAuthority():void {$a=$this->listen();$filter=static fn(string $sql):string=>str_starts_with($sql,'INSERT INTO '.\DigiForge\Database\Tables::settings().' ')&&str_contains($sql,"'stop_all'")?'UPDATE nonexistent_native_stop_write SET value=1':$sql;global $wpdb;$previous=$wpdb->suppress_errors(true);add_filter('query',$filter);try{self::assertFalse(\DigiForge\Core\Settings::set('stop_all',true));}finally{remove_filter('query',$filter);$wpdb->suppress_errors($previous);}self::assertWPError(Generation::check($a));}
 public function testNativeProtectionKeepsReturnSemanticsAndFencesAcrossItsTransaction():void {$a=$this->listen();self::assertTrue(\DigiForge\Core\Settings::protectProduction());self::assertWPError(Generation::check($a));self::assertTrue(\DigiForge\Core\Settings::get('stop_all',true));self::assertTrue(\DigiForge\Core\Settings::safety_locked());self::assertFalse(\DigiForge\Core\Settings::is_enabled('printify'));}
 public function testNativeStopFlagSuccessDoesNotFalselyAcknowledgeDrainingInFlightLease():void {$a=$this->listen();$r=Generation::withDispatchLease($a,static function(){self::assertTrue(\DigiForge\Core\Settings::set('stop_all',true));return 'LOCAL_ONLY';});self::assertWPError($r);global $wpdb;$raw=$wpdb->get_var("SELECT context FROM ".\DigiForge\Database\Tables::audit_log()." WHERE event_type='printify_acceptance_emergency_observed' ORDER BY id DESC LIMIT 1");$context=json_decode($raw,true);self::assertSame('FENCED_DRAIN_PENDING',$context['revocation_state']);self::assertTrue($context['durable_revocation_recorded']);self::assertFalse($context['dispatch_drained']);self::assertWPError(Generation::check($a));}
}
